let path=location.pathname.split('/').pop()||'index.html';if(path&&!path.endsWith('.html')&&path.indexOf('.')===-1)path+='.html';document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="/src/inner.css"><link rel="stylesheet" href="/src/premium-pages.css"><link rel="stylesheet" href="/src/page-compositions.css"><link rel="stylesheet" href="/src/content-layout.css"><link rel="stylesheet" href="/src/rich-copy.css"><style>html,body{overflow-x:hidden}.inner-content{margin-inline:auto}.source-sections{margin-inline:auto}</style>');const esc=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));const md=s=>esc(s).replace(/^#{1,6}\s*/,'').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
const parse=(t,h)=>{const raw=(t.split(new RegExp(`^# ${h}\\s*$`,'m'))[1]||'').split(/^# /m)[0];const out=[];let cur=null;raw.split(/\r?\n/).forEach(line=>{if(/^## /.test(line)){if(cur)out.push(cur);cur={title:line.replace(/^## /,'').trim(),lines:[]}}else if(cur)cur.lines.push(line)});if(cur)out.push(cur);return out.filter(x=>x.title&&x.title!=='---')};
const body=lines=>{const chunks=lines.join('\n').split(/\n\s*\n/).filter(x=>x.trim()&&x.trim()!=='---');return chunks.map(c=>{const l=c.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const ctas=l.filter(x=>/^\[.*\]$/.test(x));if(ctas.length)return l.map(x=>{if(/^\[.*\]$/.test(x)){const label=x.slice(1,-1);const href=/pricing|office/i.test(label)?'/pricing.html':'/employees.html';return `<a class="button gold panel-cta" href="${href}">${md(label)} ↗</a>`}return `<p>${md(x)}</p>`}).join('');if(l.length===1&&/^#{3,6}\s/.test(l[0]))return `<h4>${md(l[0])}</h4>`;const list=l.length>1&&(l.every(x=>/^[-*•]/.test(x))||l.every(x=>x.length<95&&!/[.!?]$/.test(x)));return list?`<ul>${l.map(x=>`<li>${md(x.replace(/^[-*•]\s*/,''))}</li>`).join('')}</ul>`:`<p>${l.map(x=>/^#{3,6}\s/.test(x)?`<span class="copy-label">${md(x)}</span>`:md(x)).join('<br>')}</p>`}).join('')};
const foot=`<footer><div><img src="/staffai-logo.png" alt="StaffAi"><p>The AI staffing agency for businesses that would rather lead than operate software.</p><p>StaffAi is a service of Studio9 LLC.<br>1012 Marquez Place, Santa Fe, NM 87505, USA<br><a href="mailto:compliance@getstaffai.com">compliance@getstaffai.com</a></p></div><div><b>Explore</b><a href="/how-it-works.html">How It Works</a><a href="/employees.html">AI Employees</a><a href="/teams.html">Teams</a><a href="/pricing.html">Pricing</a><a href="/about.html">About</a><a href="/roadmap.html">Roadmap</a><a href="/faq.html">FAQ</a></div><div><b>Legal & Trust</b><a href="/terms.html">Terms of Service</a><a href="/privacy.html">Privacy Policy</a><a href="/acceptable-use.html">Acceptable Use Policy</a><a href="/ai-disclosure.html">AI Disclosure</a><a href="/refund.html">Refund & Cancellation</a><a href="/cookies.html">Cookie Policy</a><a href="/security.html">Security</a><a href="/dpa.html">Data Processing Addendum</a><a href="/communications.html">Communications & Telephony</a></div></footer>`;
const map={'how-it-works.html':['How StaffAi Works','You say what needs to happen. Your company gets to work.','HOW IT WORKS PAGE'],'teams.html':['Teams that work together','Build the workforce your company actually needs.','TEAMS PAGE'],'pricing.html':['Pricing for your Company Office','Start with the office every company needs.','PRICING PAGE'],'about.html':['About StaffAi','An AI staffing agency built around your company.','ABOUT PAGE'],'faq.html':['Frequently Asked Questions','StaffAi, explained clearly.','FREQUENTLY ASKED QUESTIONS']};const m=map[path]||map['about.html'];fetch('/copy/site-positioning.txt').then(r=>r.text()).then(t=>{const sections=parse(t,m[2]);document.querySelector('#app').innerHTML=`<div class="announcement">Company Office launch offer: professional setup fee waived</div><header><a class="logo" href="/index.html"><img src="/staffai-logo.png" alt="StaffAi"></a><nav><a href="/how-it-works.html">How It Works</a><a href="/employees.html">AI Employees</a><a href="/teams.html">Teams</a><a href="/pricing.html">Pricing</a><a href="/about.html">About</a><a href="/roadmap.html">Roadmap</a></nav><a class="button gold" href="https://app.getstaffai.com/portal/signup?billing=monthly">Establish Your Company Office ↗</a></header><main class="page-${path.replace('.html','')}"><section class="inner-hero dark"><small class="kicker">StaffAi</small><h1>${md(m[0])}</h1><p>${md(m[1])}</p></section><section class="inner-content"><div class="source-sections">${sections.map((s,i)=>`<article><span class="section-number">${String(i+1).padStart(2,'0')}</span><h3>${md(s.title)}</h3>${body(s.lines)}</article>`).join('')}</div></section></main>${foot}`});
const repairCtas=()=>document.querySelectorAll('.source-sections p').forEach(p=>{if(/^\s*\[.*\]\s*$/.test(p.textContent)){const label=p.textContent.trim().slice(1,-1);p.outerHTML=`<a class="button gold panel-cta" href="/pricing.html">${label} ↗</a>`}});const highlightCopy=()=>document.querySelectorAll('.source-sections p').forEach(p=>{const s=p.textContent.trim();if(s.length>75||/^(AI where it makes sense|Humans where they make sense|Build the workforce your company needs|You shouldn't have to become an AI expert)/i.test(s))p.classList.add('editorial-highlight')});new MutationObserver(()=>{repairCtas();highlightCopy()}).observe(document.querySelector('#app'),{childList:true,subtree:true});setTimeout(()=>{repairCtas();highlightCopy()},300);
setTimeout(()=>document.querySelectorAll('.source-sections p,.source-sections li').forEach(p=>{if(p.textContent.trim()==='+')p.remove()}),600);
setTimeout(()=>document.querySelectorAll('a').forEach(a=>{if(/establish your company office|start.*trial|get started/i.test(a.textContent))a.href='https://app.getstaffai.com/portal/signup?billing=monthly'}),650);
